  static Material Surface(string key,int tile,float metres,Color tint,float metallic=0,float smoothness=.2f){var mat=MeshArt.Mat(key,tint);mat.shader=Resources.Load<Shader>("CitySurface");mat.SetTexture("_CityTiles",Resources.Load<Texture2DArray>("Art/WorldSurfaceArray"));mat.SetFloat("_AtlasTile",tile);mat.SetFloat("_MetersPerTile",metres);mat.SetFloat("_Metallic",metallic);mat.SetFloat("_Glossiness",smoothness);return mat;}
  public void Bind(RepairGame owner){game=owner;}
  void Update(){if(game==null||arrows==null)return;var job=game.ActiveJob;arrows.gameObject.SetActive(job!=null);Destination.gameObject.SetActive(job!=null);if(job==null)return;Destination.position=new(job.DestinationX,2,job.DestinationZ);if(displayedAddress!=job.Address){displayedAddress=job.Address;SetAddressText(addressLabel,displayedAddress,2.55f,.36f,new Vector3(-.35f,.20f,-.08f));}int metres=Mathf.Max(0,Mathf.RoundToInt(game.Distance));if(displayedMetres!=metres){displayedMetres=metres;SetAddressText(addressDistanceLabel,metres+" m",2.55f,.30f,new Vector3(-.35f,-.26f,-.08f));}int side=job.DestinationX>=0?1:-1;if(displayedSide!=side){displayedSide=side;addressSign.localPosition=new Vector3(side*4.8f,.9f,0);addressArrow.localRotation=Quaternion.Euler(0,0,side>0?0:180);}if(routeCamera==null)routeCamera=Camera.main;if(routeCamera!=null){var facing=routeCamera.transform.position-addressSign.position;facing.y=0;if(facing.sqrMagnitude>.01f)addressSign.rotation=Quaternion.LookRotation(-facing);}var from=game.Vehicle.transform.position;var direction=new Vector3(job.DestinationX-from.x,0,job.DestinationZ-from.z);if(direction.sqrMagnitude<.01f)return;var rot=Quaternion.LookRotation(direction.normalized);for(int i=0;i<arrows.childCount;i++){var a=arrows.GetChild(i);a.position=new Vector3(from.x,0,from.z)+direction.normalized*(6+i*3);a.rotation=rot;a.gameObject.SetActive(6+i*3<direction.magnitude);}}
  // TextMesh lettering faces -Z. Fit the actual glyph mesh, rather than guessing by character count.
  static void SetAddressText(TextMesh label,string words,float width,float height,Vector3 center){label.text=words;var bounds=label.GetComponent<MeshRenderer>().localBounds;float scale=Mathf.Min(1,width/Mathf.Max(.001f,bounds.size.x),height/Mathf.Max(.001f,bounds.size.y));label.transform.localScale=Vector3.one*scale;label.transform.localPosition=center-new Vector3(bounds.center.x,bounds.center.y,0)*scale;}
  static bool AtJunction(float z,float radius=9){foreach(float c in new[]{96f,220f,340f})if(Mathf.Abs(z-c)<radius)return true;return false;}
  GameObject Box(string name,Vector3 position,Vector3 scale,Material material,bool collider=false){var go=MeshArt.Box(world,name,position,scale,material);if(collider){var c=go.AddComponent<BoxCollider>();c.center=Vector3.zero;c.size=scale;}return go;}
  void Building(float x,float z,float h,int facing){
   int district=((int)(z/24)+(x>0?1:0))%4;
   // The foreground avenue uses brick terraces and mansards; offices remain on the side streets.
   if(Mathf.Abs(x)<30)district=district==0?3:district==2?1:0;
   float width=Mathf.Abs(x)>30?13:10,depth=17;
   // Keep the original collision authority, dimensions and deterministic height.
   var core=MeshArt.BevelBox(world,"Modeled masonry building core",new(x,h/2,z),new(width,h,depth),.16f,stone);
   core.AddComponent<BoxCollider>().size=new(width,h,depth);core.GetComponent<MeshRenderer>().enabled=false;
   urban.Facade(x,z,h,width,depth,facing,district);
   if(x==-18&&Mathf.Abs(z-278)<.01f)DistrictLandmarkArt.ClockTower(world,urban,new Vector3(x,0,z),h+2.9f);
  }
